/**
 * @summary Register a wallet-sent tx for optimistic "Pending" UI until the indexer confirms it
 */
export const trackTxBodyTxHashRegExp = new RegExp('^0x[0-9a-fA-F]{64}$');
export const trackTxBodyKindMax = 64;

export const trackTxBodyEntityIdMax = 64;



export const TrackTxBody = zod.object({
  "txHash": zod.string().regex(trackTxBodyTxHashRegExp),
  "kind": zod.string().min(1).max(trackTxBodyKindMax),
  "entityId": zod.string().max(trackTxBodyEntityIdMax).optional()
})

export const TrackTxResponse = zod.object({
  "txHash": zod.string(),
  "kind": zod.string(),
  "entityId": zod.string().nullable(),
  "status": zod.enum(['pending', 'mined', 'confirmed', 'failed', 'dropped']),
  "blockNumber": zod.int().nullable(),
  "confirmations": zod.int().nullable(),
  "explorerUrl": zod.string()
})


export const getTrackedTxPathTxHashRegExp = new RegExp('^0x[0-9a-fA-F]{64}$');


export const GetTrackedTxParams = zod.object({
  "txHash": zod.coerce.string().regex(getTrackedTxPathTxHashRegExp)
})

export const GetTrackedTxResponse = zod.object({
  "txHash": zod.string(),
  "kind": zod.string(),
  "entityId": zod.string().nullable(),
  "status": zod.enum(['pending', 'mined', 'confirmed', 'failed', 'dropped']),
  "blockNumber": zod.int().nullable(),
  "confirmations": zod.int().nullable(),
  "explorerUrl": zod.string()
})


/**
 * @summary Network, head block, indexer lag and relayer balance
 */
export const GetChainStatusResponse = zod.object({
  "network": zod.string(),
  "chainId": zod.int(),
  "explorerUrl": zod.string(),
  "headBlock": zod.int().nullable(),
  "indexedBlock": zod.int().nullable(),
  "lagBlocks": zod.int().nullable(),
  "indexerUpdatedAt": zod.coerce.date().nullable(),
  "confirmations": zod.int(),
  "mode": zod.union([zod.literal('LEDGER'),zod.literal('ESCROW'),zod.literal(null)]).nullable(),
  "contracts": zod.record(zod.string(), zod.string()),
  "relayer": zod.object({
  "address": zod.string(),
  "balance": zod.string().describe('Native balance in ether units.'),
  "low": zod.boolean(),
  "spentToday": zod.string(),
  "dailyCap": zod.string()
}).nullable()
})


